import React from 'react';
import { Handle } from 'reactflow';

const BaseNode = ({ data }) => {
  const { label, handles = [], content, className = '' } = data;

  return (
    <div className={`base-node ${className}`}>
      <div className="node-header">{label}</div>
      <div className="node-content">{content}</div>
      {handles.map((handle) => (
        <Handle
          key={handle.id}
          type={handle.type}
          position={handle.position}
          id={handle.id}
          className="custom-handle"
        />
      ))}
    </div>
  );
};

export default BaseNode;
